// One actual C++ positive and control fixture per source-owned analyzer rule.
#pragma once
struct AnalyzerCase {const char *rule,*positive,*negative;};
inline const AnalyzerCase analyzerCases[]{
    {"frost-self-assignment", "void f(int x){x=x;}\n", "void f(int x,int y){x=y;}\n"},
    {"frost-boolean-comparison", "bool f(bool x){return x==true;}\n", "bool f(bool x,bool y){return x==y;}\n"},
    {"frost-missing-override", "struct B{virtual void f();virtual ~B()=default;};struct D:B{void f(){}};\n", "struct B{virtual void f();virtual ~B()=default;};struct D:B{void f() override{}};\n"},
    {"frost-polymorphic-destructor", "struct B{virtual void f();};\n", "struct B{virtual void f();virtual ~B()=default;};\n"},
    {"frost-return-local-address", "int* f(){int x=0;return &x;}\n", "int* f(){static int x=0;return &x;}\n"},
    {"frost-return-move", "#include <utility>\nstruct R{R();R(R&&);};R f(){R x;return std::move(x);}\n", "#include <utility>\nstruct R{R();R(R&&);};R f(){R x;return x;}\n"},
    {"frost-identity-cast", "int f(){return static_cast<int>(1);}\n", "int f(int x){return static_cast<int>(x);}\n"},
    {"frost-constant-condition", "int f(){if(2+3==5)return 1;return 0;}\n", "int f(bool x){if(x)return 1;return 0;}\n"},
    {"frost-empty-if", "void f(bool x){if(x);}\n", "void f(bool x){if(x){}}\n"},
    {"frost-empty-loop", "void f(bool x){while(x);}\n", "void f(bool x){while(x){}}\n"},
    {"frost-assignment-condition", "int next();void f(int x){while(x=next()) {}}\n", "int next();void f(int x){while(x==next()) {}}\n"},
    {"frost-bitwise-bool", "bool f(bool a,bool b){return a&b;}\n", "bool f(bool a,bool b){return a&&b;}\n"},
    {"frost-identical-comparison", "bool f(int x){return x==x;}\n", "bool f(double x){return x==x;}\n"},
    {"frost-repeated-logical-operand", "bool f(bool x){return x&&x;}\n", "bool f(bool x,bool y){return x&&y;}\n"},
    {"frost-repeated-else-if", "int f(bool x){if(x)return 1;else if(x)return 2;return 0;}\n", "int f(bool x,bool y){if(x)return 1;else if(y)return 2;return 0;}\n"},
    {"frost-boolean-return-branch", "bool f(bool x){if(x)return true;else return false;}\n", "int f(bool x){if(x)return 1;else return 0;}\n"},
    {"frost-pointer-zero-arithmetic", "int* f(int* p){return p+0;}\n", "int* f(int* p){return p+1;}\n"},
    {"frost-sizeof-pointer-count", "unsigned f(int* p){return sizeof(p)/sizeof(*p);}\n", "unsigned f(){int p[4];return sizeof(p)/sizeof(*p);}\n"},
    {"frost-literal-address-comparison", "bool f(const char* p){return p==\"x\";}\n", "bool f(const char* p,const char* q){return p==q;}\n"},
    {"frost-out-of-range-conversion", "signed char f(){return 300;}\n", "signed char f(){return 100;}\n"},
    {"frost-divide-zero", "int f(int x){return x/0;}\n", "int f(int x){return x/2;}\n"},
    {"frost-shift-range", "int f(int x){return x<<999;}\n", "int f(int x){return x<<1;}\n"},
    {"frost-negation-overflow", "int f(){return -(-2147483647-1);}\n", "int f(){return -1;}\n"},
    {"frost-dangling-string-view", "#include <string>\n#include <string_view>\nstd::string_view f(){return std::string(\"x\");}\n", "#include <string_view>\nstd::string_view f(){return \"x\";}\n"},
    {"frost-dangling-initializer-list", "#include <initializer_list>\nstd::initializer_list<int> f(){return {1,2};}\n", "#include <initializer_list>\nstd::initializer_list<int> f(){static auto x={1,2};return x;}\n"},
    {"frost-virtual-call-constructor", "struct B{B(){f();}virtual void f();virtual ~B()=default;};\n", "struct B{B(){}virtual void f();virtual ~B()=default;};\n"},
    {"frost-throw-noexcept", "void f() noexcept{throw 1;}\n", "void f() noexcept{try{throw 1;}catch(...){}}\n"},
    {"frost-enum-switch", "enum class E{A,B};int f(E e){switch(e){case E::A:return 1;}return 0;}\n", "enum class E{A,B};int f(E e){switch(e){case E::A:return 1;case E::B:return 2;}return 0;}\n"},
    {"frost-const-move-copies", "#include <utility>\nstruct R{R(const R&);R(R&&);};void f(const R& x){R y(std::move(x));}\n", "#include <utility>\nstruct R{R(const R&);R(R&&);};void f(R& x){R y(std::move(x));}\n"},
    {"frost-range-copy", "struct R{R();R(const R&);};void f(){R values[2];for(auto x:values){}}\n", "struct R{R();R(const R&);};void f(){R values[2];for(auto& x:values){}}\n"},
    {"frost-catch-polymorphic-value", "struct B{virtual ~B()=default;};void f(){try{throw B{};}catch(B x){}}\n", "struct B{virtual ~B()=default;};void f(){try{throw B{};}catch(const B& x){}}\n"},
    {"frost-unchecked-downcast", "struct B{virtual ~B()=default;};struct D:B{};D* f(B* p){return static_cast<D*>(p);}\n", "struct B{virtual ~B()=default;};struct D:B{};D* f(B* p){return dynamic_cast<D*>(p);}\n"},
    {"frost-return-temporary-reference", "const int& f(){return 1;}\n", "const int& f(){static int x=1;return x;}\n"},
    {"frost-null-dereference", "int f(int* p){if(!p)return *p;return 0;}\n", "int f(int* p){if(!p)return 0;return *p;}\n"},
    {"frost-use-after-move", "#include <utility>\nstruct R{R();R(R&&);int read() const;};int f(){R x;R y(std::move(x));return x.read();}\n", "#include <utility>\nstruct R{R();R(R&&);int read() const;};int f(){R x;std::move(x);return x.read();}\n"},
    {"frost-empty-optional", "#include <optional>\nint f(){std::optional<int> x;return x.value();}\n", "#include <optional>\nint f(){std::optional<int> x; x.emplace(1);return x.value();}\n"},
    {"frost-delete-kind", "void f(){int* p=new int[4];delete p;}\n", "void f(){int* p=new int[4];delete[] p;}\n"},
    {"frost-unreachable", "int f(){return 1;return 2;}\n", "int f(bool b){if(b)return 1;return 2;}\n"},
};
